using System;

class Program
{
    static void Main()
    {
        Span<nint> nativeInts = stackalloc nint[4];
        nativeInts[0] = 10;
        nativeInts[1] = 20;
        nativeInts[2] = 30;
        nativeInts[3] = 40;

        Console.WriteLine($"Span<nint> length: {nativeInts.Length}");
        for (int i = 0; i < nativeInts.Length; i++)
            Console.WriteLine($"  [{i}] = {nativeInts[i]}");

        Span<nuint> unsignedNativeInts = stackalloc nuint[2];
        unsignedNativeInts[0] = 100;
        unsignedNativeInts[1] = 200;

        Console.WriteLine($"Span<nuint> length: {unsignedNativeInts.Length}");
        for (int i = 0; i < unsignedNativeInts.Length; i++)
            Console.WriteLine($"  [{i}] = {unsignedNativeInts[i]}");

        Console.WriteLine($"nint size: {sizeof(nint)} bytes");
    }
}
EOF
